#!/usr/bin/env python3
"""Produit le rapport V2 depuis les mesures Linux, sans donnée privée."""
import html,json,pathlib,re
HERE=pathlib.Path(__file__).resolve().parent;ROOT=HERE.parents[1]
OUT=ROOT/'docs/proposition/analyse';DATA=json.loads((HERE/'sorties/resultats.json').read_text());MAN=json.loads((HERE/'charges/manifest.json').read_text())
results=DATA['results'];datasets={d['label']:d for d in MAN['datasets']}
LABELS={'uniform96':'Ligne 96 o','uniform64':'Ligne 64 o + annexes','split':'Colonnes 32 + 32 o'}
def get(dataset,scale,layout):return next(r for r in results if r['dataset']==dataset and r['scale']==scale and r['layout']==layout)
def esc(v):return html.escape(str(v))
def num(v):return f'{int(v):,}'.replace(',',' ')
def mem(v):return f'{num(v)} o · {v/1048576:.3f} Mio'
def ns(v):return f'{v:.2f}'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
sections=[]
def sec(id,title,body):sections.append((id,title,f'<section id="{id}"><div class="eyebrow">Catalogue mémoire / V2</div><h2>{title}</h2>{body}</section>'))
base=get('somme-detail',1,'uniform96');compact=get('somme-detail',1,'uniform64');split=get('somme-detail',1,'split');saving=base['allocations_requested_bytes']-compact['allocations_requested_bytes'];fraction=saving/base['allocations_requested_bytes']*100
sec('verdict','Le catalogue commun est intéressant ; les 96 octets partout ne sont pas obligatoires.',f'''<p class="lead">Un seul espace d’ID pour les équipements, valeurs et actions simplifie les liens et les recherches. Le banc montre le prix exact de cette simplicité, en séparant la ligne logique de son rangement physique.</p><div class="recommend"><b>Proposition : conserver le catalogue et les identités communs ; retenir provisoirement les lignes 64 o avec extensions numériques.</b><p>Sur la forme développée des deux exports, le catalogue mesuré demande {mem(compact['allocations_requested_bytes'])}, contre {mem(base['allocations_requested_bytes'])} avec les lignes de 96 o. Économie : {mem(saving)}, soit {fraction:.1f} % du périmètre mesuré. La variante en colonnes a le même coût de données et se choisit selon les accès mesurés ci-dessous.</p></div><p>Si les bornes doivent absolument être inline pour chaque objet, le format 96 reste valide et simple ; il faut accepter ses cases inutilisées. Le choix proposé reste révisable selon les vrais schémas et les liaisons d’actions encore inconnues. Aucun code du moteur n’a été modifié.</p>''')
sec('corrections','Les corrections apportées à l’analyse précédente', '''<ul><li><b>Une référence d’annuaire n’est pas un ID stable stocké dans la ligne.</b> Le nouveau format contient un vrai id u64 et un parent u64. Un ID local est unique dans le catalogue ; l’identité entre installations est le couple installation128/local64, pas un u64 présenté comme universel.</li><li><b>Les 918 services ne sont pas 918 actions par équipement.</b> Le banc les garde comme contrats partagés. Un scénario séparé ajoute quatre liaisons matérialisées par entité pour mesurer cette sensibilité ; il s’agit d’une hypothèse, pas d’un inventaire découvert.</li><li><b>has_set n’a pas été prouvé par les exports.</b> 357 états sont candidats selon leur domaine et la présence de services usuels ; ils portent aussi ACCESS_UNRESOLVED. Ce bit ne devient jamais une permission. Sans preuve positive, l’interface ne doit pas annoncer un set disponible.</li><li><b>Les anciens totaux étaient des produits de tailles et un modèle partiel.</b> Le nouveau banc mesure réellement les allocations vivantes des tableaux, l’index ID, les liens parent/enfants et un pool de taille mesurée. Cela reste un prototype, pas le RSS de Moli complet.</li><li><b>Les dates amont ne suffisent pas.</b> Les 2 264 états exportés portent last_updated, sans last_changed/last_reported ; ni ces trois dates ni leurs cadences ne sont reconstituées. Les tests emploient trois dates synthétiques pour vérifier leurs rôles.</li><li><b>Une chaîne numérique peut rester du texte.</b> Le préparateur V2 conserve text/input_text et les formats civils en texte ; les types sensor restent une observation, jamais une déclaration complète.</li><li><b>Une case peut disparaître sans que son identité soit réemployée.</b> Le compteur d’ID refuse les reculs et débordements. La publication atomique de sa persistance et la reconstruction réelle après crash restent à implémenter.</li></ul><p>Les exports n’exposent pas unique_id dans les entrées étudiées ; les chaînes opérationnelles comptées par la V1 ne prouvaient pas une identité native stable. 13 états actifs manquent au registre et 147 n’ont pas d’équipement lié : ne pas inventer leur parent.</p>''')
sec('format','Le même objet logique, trois rangements', '''<div class="flow"><span><b>Équipement</b><br>ID unique, santé, liens</span><i>→</i><span><b>Valeur</b><br>ID, parent, get/set déclaré</span><i>→</i><span><b>Action</b><br>ID, contrat, cible facultative</span></div>'''+table(['Octets','Champ commun','Usage'],[['0–15','id u64, parent u64','Identité interne unique et lien validé ; zéro = aucun parent.'],['16–47','payload u64 et trois dates u64','Bits exacts scalaire ou handle ; observed, received, changed.'],['48–59','schema u32, aux u32, revision u32','Descriptions partagées, index annexe, révision locale.'],['60–63','flags u16, row_kind u8, value_kind u8','Catégorie device/value/action, type, qualité et capacités.'],['64–95 si inline','min/max/step/anchor, quatre u64','Bits i64/f64 selon le contrat ; présence explicite, jamais zéro=absent.']])+'''<p>Le descripteur partagé porte unité, sémantique, codec, décimales et normalisation du pourcentage. Les bornes de commande et bornes de référence de normalisation sont distinctes. Une borne de référence, une courbe ou un domaine d’observation supplémentaire doit être chiffré en plus ; le quartet ne prétend pas tout remplacer.</p>'''+table(['Variante','Rangement','Interprétation'],[['96 o','Row64 + Numeric32 dans chaque case','Même pas pour équipement, valeur, action ; bornes inutilisées réservées. Alignement naturel 8, pas de promesse d’une seule ligne de cache.'],['64 o + annexes','Row64 pour chaque objet ; Numeric32 seulement sur les formes numériques','Un format fixe commun demeure ; les descriptions de nombre sont référencées.'],['32 + 32 o + annexes','Hot32 = charge + trois dates ; Cold32 = identité + liens + flags','Même information, deux tableaux ; les boucles qui lisent les flags consultent aussi Cold32.']])+'''<p>Le schéma du banc utilise des références stub, toutes à zéro : les 918 contrats ne sont pas réellement résolus ni consultés. Le scénario liens4 ne distingue pas non plus quatre contrats exécutables ; il mesure seulement le coût de quatre fiches ciblées. Il ne teste pas un interpréteur de schémas. Le pool opaque charge les octets de données annexes, sans prétendre exécuter leurs validations. Les ID sont volontairement recherchés via HashMap dans le test lookup ; ne pas transformer la position mémoire en identité. Les slots du banc sont immuables ; suppression et compaction du catalogue ne sont pas implémentées. La séparation ID/slot n’impose pas un HashMap : une table directe ou paginée serait une autre option, avec tombstones et borne de croissance à comparer. Elle n’a pas été mesurée ici.</p>''')
sec('charges','Les deux exports, leur somme et les facteurs de charge',table(['Jeu','Équipements','Valeurs/composants','Contrats/actions','Lignes','Formes numériques','Pool annexe'],[[d['label'],num(d['devices']),num(d['values']),num(d['actions']),num(d['rows']),num(d['numeric_rows']),mem(d['payload_pool_bytes'])] for d in MAN['datasets']])+'''<p>La vue principale contient un état par entité ; la vue développée conserve tous les nœuds d’attributs, objets et listes compris. Les deux sont des vues alternatives, on ne les additionne pas. Le scénario liens4 ajoute une fiche par liaison synthétique, quatre pour chaque état principal ; il ne remplace pas les contrats partagés.</p><p>Les nombres, booléens, dates et bornes ont été remplacés par des valeurs synthétiques. La santé et les dates des équipements sont elles aussi synthétiques, sans affirmation sur leur disponibilité dans les exports. Le pool contient des octets fictifs dont la longueur vient des chaînes, contrats et structures expurgés. Les noms et données de maison n’entrent pas dans le banc public. Les bornes 0–100/pas1 servent au test de représentation et ne décrivent pas les appareils.</p>''')
memrows=[]
for dataset,scale in [('a-principal',1),('b-principal',1),('a-detail',1),('b-detail',1),('somme-principal',1),('somme-principal',10),('somme-detail',1),('somme-detail',10),('somme-detail',100),('somme-detail-liens4',1),('somme-detail-liens4',10)]:
 r=[get(dataset,scale,l) for l in LABELS]
 memrows.append([dataset+' ×'+str(scale),num(r[0]['n']),*[mem(x['allocations_requested_bytes']) for x in r]])
sec('memoire','Mémoire réellement demandée par le prototype',table(['Jeu','Lignes','96 o + index/pool','64 o + index/pool','Colonnes + index/pool'],memrows)+'''<p>Médianes de trois processus neufs. Le compteur instrumente les octets encore vivants demandés à l’allocateur système. Il inclut les capacités des vecteurs, buckets du HashMap, CSR parent/enfants et le pool touché en mémoire. Il exclut les métadonnées de malloc, la fragmentation, la fixture de référence, les buffers de chronométrage et les piles ; ce n’est pas un chiffre de mémoire totale du processus.</p>'''+table(['Composant, somme développée ×1',*[LABELS[k] for k in LABELS]],[[label,*[mem(get('somme-detail',1,l)[k]) for l in LABELS]] for label,k in [('Tableaux de fiches','fixed_bytes'),('Extensions numériques','numeric_bytes'),('Index ID → slot','index_bytes'),('Index parent → enfants','adjacency_bytes'),('Pool de données annexes','payload_pool_bytes')]])+'''<p>Le coût des trous numériques est exactement 32 × (nombre de lignes − nombre de lignes numériques) dans ce jeu, hors particularités d’index identiques. Les extensions ne sont pas internées : ce benchmark accorde déjà aux deux formats la même représentation sémantique, sans créditer un gain hypothétique de partage.</p>''')
perfrows=[]
for dataset,scale in [('somme-detail',1),('somme-detail',10),('somme-detail',100),('somme-detail-liens4',10)]:
 for layout in LABELS:
  r=get(dataset,scale,layout);perfrows.append([dataset+' ×'+str(scale),LABELS[layout],ns(r['scan_ns_per_row']),ns(r['scalar_ns_per_op']),ns(r['numeric_ns_per_op']),ns(r['lookup_ns_per_op']),ns(r['changed_update_ns_per_op']),f"{r['snapshot_ns_per_copy']/1000:.2f}"])
sec('vitesse','Les accès testés, sans transformer un microbanc en preuve produit',table(['Jeu','Format','Scan ns/ligne','Scalaire ns/op','Nombre+bornes ns/op','ID ns/op','Changement ns/op','Copie µs'],perfrows)+'''<p>Chaque essai donne la médiane de sept passages après chauffe, puis le rapport prend la médiane des trois essais séparés. Environ un million d’accès pré-calculés par passage ; leur génération reste hors chronométrage. Les snapshots mesurent allocation + copie + libération des tableaux et extensions, hors index et pool. Les mises à jour de texte/record imposent un handle immuable ou versionné (changement de handle testé, contenu du pool non interprété) : une mutation cachée sous le même handle ne serait pas détectée. Les lectures scalaires et mutations incluent les booléens/entiers/flottants, ainsi que la santé synthétique des équipements. Les accès payload/flags peuvent favoriser un format différent de la lecture des trois dates ; le détail brut contient également les mises à jour sans changement et le parcours des enfants.</p><p>Ce banc ne mesure pas verrouillage, transport, garde, abonnés, journaux, disque, rebuild de schéma ni commandes physiques. Les différences de nanosecondes dépendent du CPU et de ses caches ; aucune extrapolation à un Raspberry Pi ou au budget API p95 n’est faite.</p>''')
# Rss readback is deliberately shown separately from allocator counter.
rssrows=[]
for layout in LABELS:
 r=get('somme-detail',10,layout)
 rssrows.append([LABELS[layout],mem(r['allocations_requested_bytes']),mem(r.get('rss_anon_before_bytes',0)),mem(r.get('rss_anon_after_bytes',0)),mem(r.get('rss_anon_delta_bytes',0))])
sec('rss','RSS anonyme et budget Moli : deux périmètres différents',table(['Somme développée ×10','Allocations catalogue','RssAnon avant','RssAnon après','Delta RssAnon'],rssrows)+'''<p>Le processus de banc conserve une copie de référence de la charge, absente du futur catalogue unique. Le delta des pages anonymes à la construction est montré comme observation complémentaire ; pages, rétention de l’allocateur et bruit peuvent le distinguer des octets demandés. Il ne prouve pas le budget cgroup de Moli. Les buffers de performance sont alloués après cette lecture.</p><p>Le plafond de ce banc est 512 Mio pour permettre la fixture ×100 ; il ne modifie pas le budget produit de 32 Mio anonymes. À ×10, le catalogue doit encore laisser de la place aux transports, tâches, exécutions, caches, sécurité et autres composants. Un catalogue inférieur à 32 Mio ne prouve pas que Moli complet le sera.</p>''')
test_text=(HERE/'sorties/tests.txt').read_text();match=re.search(r'(\d+) passed; (\d+) failed',test_text);testcount=match.group(1) if match else '?'
sec('preuves','Vérifications, erreurs couvertes et limites restantes',f'''<p><b>{testcount} tests Rust passent</b>, avec compilation <code>-D warnings</code>. Les 108 essais de mesure conservent la parité exacte des champs de fiches décodés et les empreintes de contenu communes aux trois formats, à chaque charge et échelle.</p>'''+table(['Critère','État','Preuve / limite'],[['Layouts et même information','PASS','Tailles 96/64/32 ; champs décodés identiques aux entrées, pas seulement une somme de tailles.'],['ID uniques et parents valides','PASS','Doublons, parents absents, remappage ×10, compteur monotone et débordement rejetés.'],['has_set et action sans état fictif','PASS dans le prototype','Bits conservés ; action sans état ; aucune autorisation réelle déduite des candidats HA.'],['Dates : réception égale / changement','PASS','Une valeur égale rafraîchit received sans déplacer changed ; +0.0/−0.0 restent égaux ; observation amont absente conservée ; santé équipement testée.'],['i64 et bits f64','PASS','Conservation exacte de représentation ; les règles métier de quantification/conversion restent hors banc.'],['Reprise complète après crash','NON PROUVÉ','Compteur de high-water testé ; fichier atomique, annuaire stable et reprise du moteur non implémentés.'],['Toutes les actions réelles par cible','NON PROUVÉ','Contrats exportés et stress de cardinalité ; supported_features et liaisons encore incomplets.'],['Budget du processus Moli complet','NON PROUVÉ','Prototype isolé ; pas de déploiement ni de matériel commandé.']])+f'''<p>Environnement : image <code>{esc(DATA['meta']['image_id'])}</code>, Linux ARM64, un CPU alloué, limite 512 Mio. Compilation <code>{esc(DATA['meta']['compile_flags'])}</code>. Le hash source et le manifeste de charge sont conservés dans les résultats. Les trois essais sont séquentiels ; l’horloge du banc est monotone.</p><ul><li><a href="../../../tools/catalogue-banc/main.rs">Prototype Rust et tests</a> · <a href="../../../tools/catalogue-banc/README.md">Commandes et périmètre</a>.</li><li><a href="../../../tools/catalogue-banc/sorties/resultats.json">Résultats agrégés</a> · <a href="../../../tools/catalogue-banc/sorties/brut.jsonl">108 sorties brutes</a> · <a href="../../../tools/catalogue-banc/sorties/tests.txt">Tests</a>.</li><li><a href="../../../tools/catalogue-banc/charges/manifest.json">Manifeste anonymisé</a> · <a href="consolidation-entites-valeurs-actions-v1.html#deux-ha-reels">Analyse précédente et instantanés</a>.</li></ul><p>Décision proposée : conserver la normalisation logique et les ID stables, mesurer les vraies liaisons d’actions avant de figer la RAM, et préférer la ligne commune 64 o avec extensions tant que le bénéfice inline des 96 o n’est pas justifié par les accès réels.</p>''')
old=(OUT/'consolidation-entites-valeurs-actions-v1.html').read_text();css=re.search(r'<style>(.*?)</style>',old,re.S).group(1)
nav=''.join(f'<a href="#{id}">{esc(title.split(" :")[0])}</a>' for id,title,_ in sections)
body=''.join(s for _,_,s in sections)
page=f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moli — Catalogue mémoire V2 et bancs Linux</title><style>{css}</style></head><body><aside><b>Moli / Mémoire</b><p>Catalogue uniforme · V2<br>Mesures Linux ARM64</p><nav aria-label="Sections">{nav}</nav></aside><main><header><span class="badge">PROPOSITION TESTÉE — NON INTÉGRÉE AU MOTEUR</span><h1>Un catalogue commun.<br>Trois façons de le ranger.</h1><p class="lead">Équipements, valeurs, capacités et actions : la même information, des ID uniques, et des coûts vérifiés.</p></header>{body}<footer>Sources privées conservées hors dépôt · aucune commande sur une maison</footer></main></body></html>'
(OUT/'catalogue-memoire-v2.html').write_text(page)
print(json.dumps(dict(tests=testcount,uniform96=base['allocations_requested_bytes'],uniform64=compact['allocations_requested_bytes'],saving_bytes=saving,saving_percent=fraction),ensure_ascii=False))
